// src/components/AppNavbar.js — thanh điều hướng; NavLink tự gắn class "active" cho trang đang mở
import { Container, Nav, Navbar } from 'react-bootstrap';
import { Link, NavLink } from 'react-router-dom';

export default function AppNavbar() {
  return (
    <Navbar bg="dark" data-bs-theme="dark" expand="md" sticky="top">
      <Container>
        <Navbar.Brand as={Link} to="/" id="brand">💻 CodeLearn</Navbar.Brand>
        <Navbar.Toggle aria-controls="main-nav" />
        <Navbar.Collapse id="main-nav">
          <Nav className="me-auto">
            {/* end: "/" chỉ active đúng ở trang chủ, không active ở mọi trang */}
            <Nav.Link as={NavLink} to="/" end id="nav-home">Home</Nav.Link>
            <Nav.Link as={NavLink} to="/courses" id="nav-courses">Courses</Nav.Link>
          </Nav>
        </Navbar.Collapse>
      </Container>
    </Navbar>
  );
}

// src/components/Layout.js — khung chung: navbar trên cùng, nội dung trang ở <Outlet />, footer dưới cùng
import { Container } from 'react-bootstrap';
import { Outlet } from 'react-router-dom';
import AppNavbar from './AppNavbar';

export default function Layout() {
  return (
    <div className="d-flex flex-column min-vh-100">
      <AppNavbar />
      <Container as="main" id="main" className="flex-grow-1 py-4">
        <Outlet />
      </Container>
      <footer id="footer" className="bg-dark text-light text-center py-3 mt-auto small">
        © 2026 CodeLearn — FER202 final assignment
      </footer>
    </div>
  );
}

// src/pages/CoursesPage.js — (F1) trang giữ chỗ; F3 thay bằng danh sách khoá học thật
export default function CoursesPage() {
  return (
    <>
      <h2 id="courses-title">Courses</h2>
      <p className="text-muted">The course list arrives in F3.</p>
    </>
  );
}

// src/pages/HomePage.js — trang chủ: giới thiệu ngắn + nút sang danh sách khoá học
import { Col, Row } from 'react-bootstrap';
import { Link } from 'react-router-dom';

const FEATURES = [
  { icon: '🎬', title: 'Video lessons', text: 'Short, focused lessons with a video and notes.' },
  { icon: '📝', title: 'Chapter quizzes', text: 'Check what you learned at the end of every chapter.' },
  { icon: '📈', title: 'Track progress', text: 'See completed lessons and quiz scores in one place.' },
];

export default function HomePage() {
  return (
    <>
      <section className="p-5 mb-4 bg-white rounded-3 shadow-sm text-center">
        <h1 id="home-title" className="display-5 fw-bold">Learn to code with CodeLearn</h1>
        <p className="lead text-muted">Find a course, enrol, learn lesson by lesson and test yourself with quizzes.</p>
        <Link to="/courses" id="browse-btn" className="btn btn-primary btn-lg">Browse courses</Link>
      </section>
      <Row xs={1} md={3} className="g-3">
        {FEATURES.map((f) => (
          <Col key={f.title}>
            <div className="p-4 bg-white rounded-3 shadow-sm h-100">
              <div className="fs-2">{f.icon}</div>
              <h5 className="mt-2">{f.title}</h5>
              <p className="text-muted mb-0">{f.text}</p>
            </div>
          </Col>
        ))}
      </Row>
    </>
  );
}

// src/pages/NotFoundPage.js — trang 404 cho mọi đường dẫn không khớp route nào (path="*")
import { Link } from 'react-router-dom';

export default function NotFoundPage() {
  return (
    <div id="not-found" className="text-center py-5">
      <h1 className="display-1 fw-bold text-primary">404</h1>
      <p className="lead">Page not found</p>
      <p className="text-muted">The page you are looking for does not exist or has been moved.</p>
      <Link to="/" id="back-home" className="btn btn-primary">Back to home</Link>
    </div>
  );
}

// src/App.js — khai báo MỌI route của CodeLearn ở một chỗ (nhìn là thấy cả sơ đồ trang)
import { Route, Routes } from 'react-router-dom';
import Layout from './components/Layout';
import HomePage from './pages/HomePage';
import CoursesPage from './pages/CoursesPage';
import NotFoundPage from './pages/NotFoundPage';

export default function App() {
  return (
    <Routes>
      {/* Layout chung: navbar + <Outlet /> + footer cho mọi trang */}
      <Route element={<Layout />}>
        {/* ── Khách (guest) xem được ── */}
        <Route path="/" element={<HomePage />} />
        <Route path="/courses" element={<CoursesPage />} />

        {/* Mọi đường dẫn không khớp ⇒ 404 (luôn để CUỐI) */}
        <Route path="*" element={<NotFoundPage />} />
      </Route>
    </Routes>
  );
}

